    def __init__(self, rate, burst):
        if rate <= 0 or burst < 1:
            raise ValueError("Rate must be > 0 and burst must be >= 1")
        self.rate = rate
        self.burst = burst
        self.keys = {}

    def allow(self, key, now):
        if key not in self.keys:
            # A new key starts full
            self.keys[key] = {
                'tokens': float(burst),
                'last_update': now
            }

        key_data = self.keys[key]
        last_now = key_data['last_update']

        if now < last_now:
            raise ValueError("Time cannot go backwards")

        # Refill tokens
        delta_time = now - last_now
        refill = delta_time * self.rate
        new_tokens = min(float(self.burst), key_data['tokens'] + refill)

        key_data['tokens'] = new_tokens
        key_data['last_update'] = now

        if key_data['tokens'] >= 1:
            key_data['tokens'] -= 1
            return True

        return False
